```json
{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, attr_k8s_pod_name, metric, value FROM abnormal_metrics WHERE metric = 'k8s.container.ready' AND attr_k8s_pod_name LIKE 'profile%' ORDER BY time",
          "claim": "The profile pod reports container ready=0 for the entire abnormal window, versus ready=1 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS p, MAX(value) AS max_restarts FROM abnormal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name LIKE 'profile%' UNION ALL SELECT 'norm', MAX(value) FROM normal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name LIKE 'profile%'",
          "claim": "Profile container restarts rise to 2–6 in the abnormal window, while normal stays at 0."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS p, attr_status_code, COUNT(*) AS n FROM abnormal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Client' AND span_name = 'profile.Profile/GetProfiles' GROUP BY 1,2 UNION ALL SELECT 'norm', attr_status_code, COUNT(*) FROM normal_traces WHERE service_name = 'frontend' AND attr_span_kind = 'Client' AND span_name = 'profile.Profile/GetProfiles' GROUP BY 1,2",
          "claim": "Frontend's GetProfiles calls to profile return Error 2321 times in abnormal and never in normal; profile has no abnormal spans."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, COUNT(*) AS n FROM abnormal_logs WHERE level = 'ERROR' GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Frontend logs 'Get profiles failed' at ERROR level 1155 times during the abnormal window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, COUNT(*) AS n, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'profile.Profile/GetProfiles' OR (service_name = 'frontend' AND attr_span_kind = 'Server' AND attr_status_code = 'Error') GROUP BY ALL ORDER BY n DESC",
          "claim": "Frontend client calls to profile fail fast (p95 about 0.02 ms), and frontend server spans return HTTP 500 for the same requests."
        }
      ]
    }
  ]
}
```

